class Solution {
    int gcd(int a, int b) {
        while (b) { int t = a % b; a = b; b = t; }
        return a;
    }
public:
    int distinctSequences(int n) {
        const int MOD = 1e9 + 7;
        if (n == 1) return 6;

        // dp[a][b]: count of valid sequences ending with rolls (a, b)
        vector<vector<long long>> dp(7, vector<long long>(7, 0));
        for (int a = 1; a <= 6; a++)
            for (int b = 1; b <= 6; b++)
                if (a != b && gcd(a, b) == 1)
                    dp[a][b] = 1;

        for (int len = 3; len <= n; len++) {
            vector<vector<long long>> ndp(7, vector<long long>(7, 0));
            for (int a = 1; a <= 6; a++) {
                for (int b = 1; b <= 6; b++) {
                    if (a == b || gcd(a, b) != 1) continue;
                    for (int p = 1; p <= 6; p++) {
                        if (p == a || p == b || gcd(p, a) != 1) continue;
                        ndp[a][b] = (ndp[a][b] + dp[p][a]) % MOD;
                    }
                }
            }
            dp = move(ndp);
        }

        long long ans = 0;
        for (int a = 1; a <= 6; a++)
            for (int b = 1; b <= 6; b++)
                ans = (ans + dp[a][b]) % MOD;
        return (int)ans;
    }
};
